"""Render transparent offline experiment summaries from saved JSON only."""
import json
import html
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from mtr_project.paths import ROOT,write_json,sha256

SHORT={'Keep the lane.':'Keep lane','Go straight.':'Straight','Slow down.':'Slow down','Stop.':'Stop',
       'Remain stopped.':'Stay stopped','Merge to the left lane.':'Merge left','Merge to the right lane.':'Merge right',
       'Turn left.':'Turn left','Turn right.':'Turn right'}
REASONS={'motion':'Motion limits','constant_velocity_collision':'CV actor overlap',
         'refinement_deviation':'Refinement > 1 m','observed_start_road_route':'Observed start / route',
         'road_footprint':'Vehicle body on road'}

def main():
    base=ROOT/'runs/project-v2/baseline-v1';dest=ROOT/'runs/project-v2/reports';dest.mkdir(exist_ok=True)
    reports={s:json.loads((base/f'{s}-evaluation.json').read_text()) for s in ['development','evaluation']}
    freeze=json.loads((base/'frozen-baseline.json').read_text())
    mismatch=[p for p,digest in freeze['files'].items() if sha256(ROOT/p)!=digest]
    if mismatch:raise ValueError('Frozen baseline changed: '+', '.join(mismatch))
    expected=9
    for split,report in reports.items():
        if len(report['windows'])!=expected:raise ValueError(f'{split} incomplete; expected {expected} windows')
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,
                         'axes.titleweight':'bold','axes.labelcolor':'#243b50','text.color':'#243b50','figure.facecolor':'white'})
    fig,axes=plt.subplots(2,2,figsize=(13,8.5),gridspec_kw={'width_ratios':[1,1.4]})
    colors={'development':'#147e83','evaluation':'#d79548'}
    instructions=list(SHORT)
    for offset,(split,report) in enumerate(reports.items()):
        rows=report['windows'];summary=report['summary'];x=np.arange(len(rows))
        ax=axes[0,0];ax.plot(x,[r['passing_count'] for r in rows],marker='o',label=split,color=colors[split]);ax.set_ylim(0,64)
        ax.set_xticks(x,[f'{i//3+1}/{[20,50,80][i%3]}%' for i in range(9)],rotation=40,ha='right')
        ax.set_title('Candidates surviving every fixed check');ax.set_ylabel('Candidates / 64');ax.set_xlabel('Recording / anchor fraction');ax.legend(frameon=False)
        ax=axes[0,1];selected=[summary['by_diagnostic_instruction'][i]['selected'] for i in instructions]
        ax.barh(np.arange(len(instructions))+(offset-.5)*.36,selected,height=.34,label=split,color=colors[split]);ax.set_yticks(np.arange(len(instructions)),[SHORT[i] for i in instructions]);ax.invert_yaxis() if offset==0 else None
        ax.set_xlim(0,9);ax.set_xticks(range(10));ax.set_title('Diagnostic instruction selection coverage');ax.set_xlabel('Windows with a proposed trajectory / 9')
        rejects={}
        for row in rows:
            for reason,count in row['rejections'].items():rejects[reason]=rejects.get(reason,0)+count
        axes[1,offset].barh([REASONS.get(k,k) for k in rejects],list(rejects.values()),color=colors[split]);axes[1,offset].invert_yaxis()
        axes[1,offset].set_xlim(0,576)
        axes[1,offset].set_title(split.capitalize()+': rejection reasons (overlap)');axes[1,offset].set_xlabel('Candidates rejected / 576')
    fig.suptitle('Language-guided MTR: independent-recording offline baseline',fontsize=17,y=.995)
    fig.text(.02,.012,'Fixed 20/50/80% anchors · 3 development + 3 held-out recordings · Rejection counts overlap\nCoverage is not semantic accuracy or closed-loop success; all checks are assumption-limited.',fontsize=9,color='#627486')
    fig.tight_layout(rect=[0,.065,1,.97]);fig.savefig(dest/'baseline-overview.png',dpi=180);fig.savefig(dest/'baseline-overview.pdf');plt.close(fig)
    parser=json.loads((ROOT/'runs/project-v2/language/parser-coverage.json').read_text())
    rows=[]
    for split,report in reports.items():
        for r in report['windows']:
            rows.append('<tr><td>'+html.escape(r['scene']['key'])+'</td><td>'+f"{r['current_speed_mps']:.1f}"+'</td><td>'+str(r['passing_count'])+'/64</td><td>'+', '.join(SHORT[c['instruction']] for c in r['diagnostic_choices'] if c['selected_candidate'] is not None)+'</td></tr>')
    summaries=[]
    for split,report in reports.items():
        s=report['summary'];available=sum(r['passing_count']>0 for r in report['windows'])
        summaries.append(f'<li><strong>{split}</strong>：{s["recordings"]} \u6bb5\u72ec\u7acb\u8bb0\u5f55、{s["windows"]} \u4e2a\u7a97\u53e3，{s["passing_candidates"]}/576 \u6761\u5019\u9009\u901a\u8fc7\u5168\u90e8\u5f53\u524d\u68c0\u67e5；{available}/9 \u4e2a\u7a97\u53e3\u81f3\u5c11\u6709\u4e00\u6761\u53ef\u7528\u5019\u9009。</li>')
    document='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>ECE191 \u79bb\u7ebf\u7814\u7a76\u7ed3\u679c</title><style>
body{max-width:1050px;margin:45px auto;padding:0 25px;font:16px/1.75 Segoe UI,Arial;color:#243b50}h1,h2{color:#147e83}img{max-width:100%}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:8px;border-bottom:1px solid #dce3e8}aside{background:#fff4e5;padding:18px;border-left:4px solid #d79548}code{background:#edf2f5;padding:2px 5px}</style>
<h1>ECE191：\u8bed\u8a00\u5f15\u5bfc MTR \u79bb\u7ebf\u539f\u578b</h1><nav><a href="/">\u5019\u9009\u8f68\u8ff9</a> · <a href="/alignment">\u89c6\u9891\u4e0e\u6807\u6ce8\u5bf9\u5e94</a> · <a href="/replay">\u591a\u9636\u6bb5\u56de\u653e</a></nav><p>\u6570\u636e → MTR \u5019\u9009 → \u6709\u9650\u68c0\u67e5 → \u8bed\u8a00\u52a8\u4f5c\u5339\u914d → \u63d0\u51fa\u4e00\u6761\u5019\u9009。\u6a21\u578b\u6ca1\u6709\u91cd\u65b0\u8bad\u7ec3，\u8bed\u8a00\u6ca1\u6709\u8fdb\u5165 MTR \u5185\u90e8。</p>
<aside>\u672c\u9875\u62a5\u544a\u79bb\u7ebf\u5b9e\u9a8c，\u4e0d\u4ee3\u8868\u8f66\u8f86\u771f\u7684\u6267\u884c\u4e86\u6240\u9009\u8def\u7ebf。\u65b0\u8bb0\u5f55\u7684\u8bed\u8a00\u6307\u4ee4\u662f\u7edf\u4e00\u8bca\u65ad\u6307\u4ee4，\u5c1a\u672a\u8bc1\u660e\u4e0e doPlan \u89c6\u9891\u6807\u6ce8\u7cbe\u786e\u5bf9\u9f50。</aside>
<h2>\u8fd9\u6b21\u9a8c\u8bc1\u4e86\u4ec0\u4e48</h2><ul>'''+''.join(summaries)+'''</ul><img src="baseline-overview.png" alt="\u5019\u9009\u901a\u8fc7\u60c5\u51b5、\u8bed\u8a00\u8986\u76d6\u548c\u62d2\u7edd\u539f\u56e0">
<h2>\u6bcf\u4e2a\u7a97\u53e3\u7684\u5b8c\u6574\u7ed3\u679c</h2><p>“\u53ef\u9009\u52a8\u4f5c”\u53ea\u662f\u5f53\u524d\u89c4\u5219\u627e\u5230\u5339\u914d\u5019\u9009，\u4e0d\u662f\u4eba\u5de5\u9a8c\u8bc1\u7684\u8bed\u8a00\u51c6\u786e\u7387。\u6ca1\u6709\u52a8\u4f5c\u65f6\u7cfb\u7edf\u62d2\u7edd\u9009\u8def。</p><table><thead><tr><th>\u7a97\u53e3</th><th>\u901f\u5ea6 m/s</th><th>\u901a\u8fc7\u68c0\u67e5</th><th>\u53ef\u9009\u52a8\u4f5c</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table>
<h2>\u8bed\u8a00\u80fd\u529b\u7684\u5b9e\u9645\u8303\u56f4</h2><p>doPlan \u53d1\u5e03\u8868\u6709 5,198 \u6761\u975e\u7a7a\u6307\u4ee4。\u65e7\u89c4\u5219\u5b8c\u6574\u63a5\u53d7 109 \u6761；\u65b0\u89c4\u5219\u5b8c\u6574\u63a5\u53d7 '''+str(parser['v2_counts']['parsed'])+''' \u6761。\u89e3\u6790\u6210\u529f\u4e5f\u4e0d\u7b49\u4e8e\u5177\u5907\u6267\u884c\u6240\u9700\u7684\u4ea4\u901a\u706f、\u5730\u6807\u6216\u8f66\u8f86\u5bf9\u8c61\u5bf9\u5e94\u5173\u7cfb。\u65e0\u6cd5\u5b8c\u6574\u7406\u89e3\u7684\u53e5\u5b50\u4e0d\u4f1a\u5220\u6389\u6761\u4ef6\u540e\u7ee7\u7eed\u9009\u8def。</p>
<h2>\u8fdb\u4e00\u6b65\u6838\u5bf9</h2><ul><li>\u539f\u59cb\u793a\u4f8b\u7247\u6bb5\u7684 9 \u4e2a\u89c6\u9891\u5404\u6709 1,035 \u5e27，\u4e0e GPS \u884c\u6570\u4e00\u81f4；\u6240\u6709 GPS \u65f6\u95f4\u548c\u4f4d\u7f6e\u5747\u5bf9\u5e94\u539f\u59cb\u6570\u636e\u5e93。\u8fd9\u4e2a\u7ed3\u8bba\u53ea\u8986\u76d6\u4e00\u6bb5\u89c6\u9891。</li><li>\u6807\u6ce8\u662f\u89c6\u9891\u7a97\u53e3，\u4e0d\u5305\u542b\u5df2\u77e5\u7684\u4e58\u5ba2\u8bf4\u8bdd\u65f6\u523b；\u539f\u59cb\u76f8\u673a\u56fe\u7247\u4e0e\u89c6\u9891\u751f\u6210\u7248\u672c\u5c1a\u672a\u72ec\u7acb\u8ba4\u8bc1。</li><li>\u4e09\u4e2a\u5f00\u53d1\u7a97\u53e3\u6e05\u7a7a\u5168\u90e8\u672a\u6765\u8f66\u8f86\u72b6\u6001\u540e，MTR \u8f68\u8ff9、\u5206\u6570\u548c\u7f16\u53f7\u5747\u672a\u6539\u53d8。\u8fd9\u662f\u5df2\u6267\u884c\u7684\u56de\u5f52\u68c0\u67e5，\u4e0d\u662f\u5bf9\u6240\u6709\u914d\u7f6e\u7684\u8bc1\u660e。</li><li>\u5c1d\u8bd5\u5386\u53f2\u76f4\u7ebf/\u8f6c\u5f2f\u5916\u63a8\u5468\u8f66\u540e，\u5f00\u53d1\u96c6 6 \u79d2\u5e73\u5747\u4f4d\u7f6e\u8bef\u5dee\u7ea6 4.39/4.62 \u7c73，\u539f\u5300\u901f\u65b9\u6cd5\u7ea6 4.06 \u7c73；\u56e0\u6b64\u4fdd\u7559\u539f\u57fa\u7ebf。\u6bd4\u8f83\u4f7f\u7528\u540c\u4e00\u6279 138 \u4e2a\u6709\u6548\u5468\u8f66\u6837\u672c。</li></ul>
<h2>\u5df2\u53d1\u73b0\u7684\u95ee\u9898</h2><ul><li>6 \u79d2\u5300\u901f\u5468\u8f66\u9884\u6d4b\u53ef\u80fd\u660e\u663e\u504f\u79bb\u771f\u5b9e\u9a7e\u9a76；\u5f00\u53d1\u96c6\u4e24\u4e2a\u6848\u4f8b\u504f\u5dee\u7ea6 4.5 \u7c73\u548c 9.7 \u7c73。</li><li>\u8f66\u9053\u591a\u8fb9\u5f62\u68c0\u67e5\u53ef\u80fd\u62d2\u7edd\u5f53\u524d\u5df2\u9760\u8fd1\u8fb9\u7f18\u7684\u8f66\u8eab。\u4fdd\u7559\u539f\u9608\u503c，\u5355\u72ec\u8bb0\u5f55\u8bef\u5dee。</li><li>MTR \u662f\u9884\u6d4b\u6a21\u578b；\u5b83\u7684\u9ad8\u5206\u5019\u9009\u5e38\u63a5\u8fd1\u539f\u9a7e\u9a76\u884c\u4e3a，\u4e0d\u4fdd\u8bc1\u8986\u76d6\u7528\u6237\u60f3\u8981\u7684\u53e6\u4e00\u79cd\u52a8\u4f5c。</li><li>\u591a\u9636\u6bb5\u8ddf\u8e2a\u53ea\u4f7f\u7528\u5df2\u7ecf\u89c2\u5bdf\u5230\u7684\u52a8\u4f5c；\u8bb0\u5f55\u56de\u653e\u6ca1\u6709\u6267\u884c\u6211\u4eec\u9009\u62e9\u7684\u8def\u7ebf。</li><li>\u539f\u59cb\u793a\u4f8b\u7684\u771f\u5b9e\u5e76\u7ebf\u6807\u6ce8\u5c1a\u672a\u88ab\u52a8\u4f5c\u68c0\u6d4b\u5668\u786e\u8ba4；\u9700\u6838\u5bf9\u5730\u56fe\u8fde\u63a5\u5904\u7684\u5b9a\u4f4d\u548c\u68c0\u6d4b\u8986\u76d6，\u4e0d\u80fd\u76f4\u63a5\u5224\u5b9a\u6807\u6ce8\u9519\u8bef。</li></ul>
<h2>\u590d\u73b0</h2><p>\u9879\u76ee <code>historical-project</code>；Ubuntu \u5bf9\u5e94 <code>historical-project</code>。\u5728 Ubuntu \u9879\u76ee\u76ee\u5f55\u8fd0\u884c <code>bash run_wsl.sh project_demo.py</code>，\u7136\u540e\u6253\u5f00 <a href="http://localhost:8765">\u672c\u5730\u6f14\u793a</a>。</p><p>\u5b8c\u6574 JSON：<code>runs/project-v2/baseline-v1</code>；\u8bc4\u4f30\u524d\u6e90\u4ee3\u7801\u6307\u7eb9：<code>frozen-baseline.json</code>。\u62a5\u544a\u7531\u4fdd\u5b58\u7684 JSON \u751f\u6210，\u6ca1\u6709\u518d\u6b21\u8ba1\u7b97\u6a21\u578b。</p></html>'''
    extra_sources=['runs/project-v2/future-mask-audit/summary.json',
                   'runs/project-v2/actor-forecast/development-comparison-v2.json',
                   'runs/project-v2/video-alignment/2021.06.09.12.39.51_veh-26_05332_05540/alignment-evidence.json']
    extra_sections=''
    comparison_path=ROOT/'runs/project-v2/replay-diagnostics/observer-comparison.json'
    if comparison_path.exists():
        comparison=json.loads(comparison_path.read_text());extra_sources.append(str(comparison_path.relative_to(ROOT)))
        table=[]
        for row in comparison['comparisons']:
            details=', '.join(f'{e["action"]} @ {e["seconds_from_first_lidar"]:.1f}s' for e in row['new_or_more_than_two_seconds_shifted_events'])
            table.append('<tr><td>'+html.escape(row['replay'])+'</td><td>'+html.escape(details or '\u65e0')+'</td></tr>')
        extra_sections+='<h2>\u8de8\u5730\u56fe\u8fde\u63a5\u533a\u57df\u7684\u52a8\u4f5c\u68c0\u6d4b\u5b9e\u9a8c</h2><p>\u539f\u7248\u6ca1\u6709\u786e\u8ba4\u539f\u59cb\u793a\u4f8b\u7684\u53f3\u5e76\u7ebf；\u65b0\u65b9\u6cd5\u4fdd\u7559\u77ed\u6682\u5b9a\u4f4d\u4e2d\u65ad\u524d\u7684\u9053\u8def\u5bf9\u5e94\u5173\u7cfb，\u518d\u8981\u6c42\u8f66\u8eab\u5728\u76ee\u6807\u9053\u8def\u7a33\u5b9a。\u539f\u6709\u52a8\u4f5c\u5747\u4fdd\u7559，\u56db\u6bb5\u8bb0\u5f55\u5404\u65b0\u589e\u4e00\u4e2a\u5e76\u7ebf\u4e8b\u4ef6。\u65b0\u589e\u4e8b\u4ef6\u4ecd\u9700\u4eba\u5de5\u6838\u9a8c，\u4e0d\u662f\u51c6\u786e\u7387\u63d0\u9ad8\u7684\u8bc1\u660e。\u65f6\u95f4\u4ee5\u5404\u6570\u636e\u5e93\u7b2c\u4e00\u6761 LiDAR \u8bb0\u5f55\u4e3a\u96f6\u70b9。</p><table><tr><th>\u56de\u653e</th><th>\u65b0\u589e/\u660e\u663e\u63d0\u524d\u7684\u89c2\u6d4b\u4e8b\u4ef6</th></tr>'+''.join(table)+'</table>'
    sequence_path=ROOT/'runs/project-v2/annotation-sequence-v1/sequence-report.json'
    if sequence_path.exists():
        sequence=json.loads(sequence_path.read_text());extra_sources.append(str(sequence_path.relative_to(ROOT)))
        labels={'selected_conditionally':'\u63d0\u51fa\u5019\u9009','no_matching_candidate':'\u6ca1\u6709\u5339\u914d\u5019\u9009','completed':'\u5df2\u89c2\u6d4b\u5230\u4efb\u52a1\u5b8c\u6210'}
        table=[]
        for row in sequence['checkpoints']:
            result=row['selection'];status=labels.get(result['status'],result['status'])
            table.append(f'<tr><td><a href="/?scene={html.escape(row["key"],quote=True)}">{row["video_frame"]}</a></td><td>{row["gps_elapsed_seconds"]:.1f}</td><td>{row["passing_candidates"]}/64</td><td>{html.escape(status)}</td><td>{result["candidate"] if result["candidate"] is not None else "—"}</td></tr>')
        extra_sections+='<h2>\u540c\u4e00\u6bb5\u9a7e\u9a76\u4e2d\u7684\u6301\u7eed\u8bed\u8a00\u4efb\u52a1</h2><p>\u6307\u4ee4\u4e3a Merge to the right lane.。8 \u4e2a\u65f6\u523b\u5206\u522b\u91cd\u65b0\u751f\u6210 MTR \u5019\u9009，\u4efb\u52a1\u5728\u4e2d\u95f4\u6301\u7eed\u4fdd\u7559，\u7531\u5df2\u89c2\u6d4b\u52a8\u4f5c\u51b3\u5b9a\u5b8c\u6210\u72b6\u6001。\u7a97\u53e3\u8d77\u70b9\u4f5c\u4e3a\u6f14\u793a\u6fc0\u6d3b\u70b9，\u5b9e\u9645\u8bf4\u8bdd\u65f6\u95f4\u672a\u77e5；\u8fd9\u4e9b\u65f6\u523b\u662f\u5728\u67e5\u770b\u8be5\u4f8b\u540e\u9009\u62e9\u7684。\u5019\u9009\u6ca1\u6709\u88ab\u6267\u884c。</p><table><tr><th>\u89c6\u9891\u5e27（\u70b9\u51fb\u770b\u5019\u9009）</th><th>GPS \u65f6\u95f4 s</th><th>\u901a\u8fc7\u68c0\u67e5</th><th>\u4efb\u52a1\u72b6\u6001</th><th>\u6240\u9009\u7f16\u53f7</th></tr>'+''.join(table)+'</table><p>\u70b9\u51fb\u5019\u9009\u9875\u9762\u4f1a\u91cd\u65b0\u5f00\u59cb\u4e00\u6b21\u5355\u65f6\u523b\u6307\u4ee4；\u4e0a\u8868\u624d\u662f\u4fdd\u7559\u4efb\u52a1\u5386\u53f2\u7684\u8fde\u7eed\u56de\u653e\u7ed3\u679c。</p>'
    variant_path=sequence_path.with_name('sequence-report-map-tail-v1.json')
    if variant_path.exists():
        variant=json.loads(variant_path.read_text());extra_sources.append(str(variant_path.relative_to(ROOT)))
        table=[]
        for row in variant['checkpoints']:
            choice=row['selection']['candidate']
            if choice is None:continue
            source=ROOT/'runs'/row['run']/'anchored_feasibility.json'
            if sha256(source)!=row['screen_sha256']:raise ValueError('Variant screen changed')
            extra_sources.append(str(source.relative_to(ROOT)))
