        extra_sections+='<h2>\u5730\u56fe\u5f15\u5bfc\u7684\u5c0f\u5e45\u8c03\u6574：\u72ec\u7acb\u5b9e\u9a8c\u7248\u672c</h2><p>\u5148\u5141\u8bb8\u62d3\u6251\u5173\u7cfb\u4e00\u81f4\u7684\u76f8\u90bb\u5e73\u884c\u8fde\u63a5\u533a\u57df\u4e4b\u95f4\u53d8\u9053，\u518d\u5bf9\u5df2\u6709\u5355\u6b21\u53f3\u5e76\u7ebf\u5019\u9009\u7684\u540e\u4e09\u79d2\u4f5c\u5c0f\u5e45\u6a2a\u5411\u8c03\u6574。\u524d\u9762\u4e09\u79d2\u4fdd\u6301\u4e0d\u53d8；\u6bcf\u6b21\u8c03\u6574\u91cd\u65b0\u68c0\u67e5\u8fd0\u52a8、\u9053\u8def\u8f66\u8eab、\u5468\u8f66\u5300\u901f\u5047\u8bbe\u78b0\u649e、\u4e0e\u539f\u59cb\u5019\u9009\u7684\u504f\u5dee，\u4ee5\u53ca\u76ee\u6807\u8f66\u9053\u5185\u7684\u7a33\u5b9a\u65f6\u95f4。\u901a\u8fc7\u68c0\u67e5\u540e\u624d\u63d0\u51fa\u5019\u9009。</p><table><tr><th>\u89c6\u9891\u5e27</th><th>GPS \u65f6\u95f4 s</th><th>\u5019\u9009</th><th>\u989d\u5916\u6a2a\u79fb\u5e45\u5ea6</th><th>\u8ddd\u539f\u59cb MTR \u6700\u5927\u504f\u5dee</th></tr>'+''.join(table)+'</table><p>190 \u79d2\u548c 195 \u79d2\u53ef\u63d0\u51fa\u5019\u9009；\u66f4\u65e9\u7684\u4e94\u4e2a\u68c0\u67e5\u70b9\u4ecd\u62d2\u7edd\u9009\u8def。\u7ea6 197.5 \u79d2\u7684\u5b8c\u6210\u4e8b\u4ef6\u6765\u81ea\u8bb0\u5f55\u4e2d\u7684\u53f8\u673a，\u4e0d\u662f\u8fd9\u4e9b\u5019\u9009\u88ab\u6267\u884c\u7684\u7ed3\u679c。\u8bed\u8a00\u9009\u62e9\u6cbf\u7528\u539f\u5019\u9009\u5206\u6570\u6392\u5e8f；\u65b0\u66f2\u7ebf\u6ca1\u6709\u7ecf\u8fc7\u6a21\u578b\u91cd\u65b0\u8bc4\u5206。</p><aside>\u8fd9\u662f\u770b\u8fc7\u672c\u4f8b\u540e\u7684\u5f00\u53d1\u5b9e\u9a8c，\u5c1a\u65e0\u72ec\u7acb\u9a8c\u8bc1。\u51e0\u4f55\u4e0a\u76f8\u90bb\u4e0d\u8bc1\u660e\u6807\u7ebf\u5141\u8bb8\u53d8\u9053；\u8fd0\u52a8\u9608\u503c\u4e0d\u7b49\u4e8e\u8f66\u8f86\u52a8\u529b\u5b66\u53ef\u6267\u884c\u6027。\u4e0d\u80fd\u628a\u4e24\u6b21\u63d0\u51fa\u5019\u9009\u79f0\u4e3a\u6210\u529f\u7387。</aside>'
