        extra_sections+='<h2>\u540c\u4e00\u8c03\u6574\u65b9\u6cd5\u5728\u53e6\u5916\u4e09\u6bb5\u5f00\u53d1\u8bb0\u5f55\u4e0a\u7684\u7ed3\u679c</h2><p>\u4f7f\u7528\u539f\u6765\u56fa\u5b9a\u7684 20% / 50% / 80% \u65f6\u523b，\u5171\u4e5d\u4e2a\u7a97\u53e3；\u590d\u7528\u76f8\u540c MTR \u8f93\u51fa，\u4e0d\u6839\u636e\u65b0\u7ed3\u679c\u518d\u8c03\u9608\u503c。\u5de6\u5e76\u7ebf\u4ece\u96f6\u4e2a\u53ef\u9009\u7a97\u53e3\u589e\u52a0\u5230\u4e00\u4e2a，\u53f3\u5e76\u7ebf\u7684\u7a97\u53e3\u6570\u91cf\u4e0d\u53d8。\u65b0\u589e\u5de6\u5e76\u7ebf\u5019\u9009\u7684\u5c3e\u90e8\u8c03\u6574\u4e3a 0.70 \u7c73，\u4e0e\u539f\u59cb MTR \u6700\u5927\u504f\u5dee\u7ea6 0.712 \u7c73。</p><table><tr><th>\u65b9\u6cd5</th><th>\u901a\u8fc7\u68c0\u67e5\u7684\u5019\u9009</th><th>\u53ef\u63d0\u51fa\u5de6\u5e76\u7ebf\u7684\u7a97\u53e3</th><th>\u53ef\u63d0\u51fa\u53f3\u5e76\u7ebf\u7684\u7a97\u53e3</th></tr>'+''.join(table)+'</table><p><a href="/?scene=map-tail-development-v1--development-00-f800">\u6253\u5f00\u8fd9\u4e2a\u5f00\u53d1\u7a97\u53e3</a>，\u5206\u522b\u9009\u62e9\u5de6\u53f3\u5e76\u7ebf\u6307\u4ee4\u6bd4\u8f83\u8def\u7ebf。\u4e5d\u4e2a\u7a97\u53e3\u4e2d\u53ea\u6709\u4e00\u4e2a\u51fa\u73b0\u53ef\u7528\u7684\u65b0\u589e\u5de6\u5e76\u7ebf，\u8bf4\u660e\u6548\u679c\u6709\u9650。\u8fd9\u91cc\u7684\u6307\u4ee4\u662f\u8bca\u65ad\u6307\u4ee4，\u4e0d\u662f\u5bf9\u4eba\u5de5\u6807\u6ce8\u7684\u6b63\u786e\u7387\u6d4b\u91cf；\u4e09\u6bb5\u8bb0\u5f55\u7528\u4e8e\u5f00\u53d1，\u4e0d\u80fd\u79f0\u4e3a\u76f2\u6d4b。</p><p>\u5ba1\u8ba1\u786e\u8ba4：\u539f\u59cb\u6a21\u578b\u6570\u7ec4\u672a\u6539\u5199；\u4ec5\u8c03\u6574\u5730\u56fe\u5339\u914d\u65f6\u8f68\u8ff9\u4e0d\u53d8；\u5c3e\u90e8\u8c03\u6574\u4fdd\u7559\u524d\u4e09\u79d2；\u4fee\u6539\u540e\u7684\u5019\u9009\u91cd\u65b0\u901a\u8fc7\u5f53\u524d\u68c0\u67e5\u4e14\u8ddd\u539f\u59cb\u8f68\u8ff9\u4e0d\u8d85\u8fc7\u4e00\u7c73。</p>'
