        extra_sections+='<h2>\u91cd\u8981\u4fee\u6b63：\u4e09\u6761\u5efa\u8bae\u5bf9\u8f66\u8eab\u671d\u5411\u5047\u8bbe\u654f\u611f</h2><p>39 \u6761\u65e2\u6709\u8def\u7ebf\u7684\u539f\u59cb\u8f66\u8eab\u548c\u78b0\u649e\u68c0\u67e5\u5168\u90e8\u6210\u529f\u590d\u73b0。\u4f4d\u7f6e\u70b9\u5b8c\u5168\u4e0d\u53d8，\u53ea\u628a\u8f66\u8eab\u65b9\u5411\u4ece\u8def\u7ebf\u5207\u7ebf\u6362\u6210\u540e\u8f6e\u65e0\u4fa7\u6ed1\u6a21\u578b\u63a8\u5bfc\u7684\u65b9\u5411：\u9053\u8def\u68c0\u67e5\u4ecd\u5168\u90e8\u901a\u8fc7、\u5300\u901f\u5468\u8f66\u78b0\u649e\u4ecd\u672a\u89e6\u53d1，\u4f46 3 \u6761\u8def\u7ebf\u4e0d\u518d\u6ee1\u8db3\u6700\u540e\u534a\u79d2\u8f66\u8eab\u5b8c\u5168\u8fdb\u5165\u76ee\u6807\u8f66\u9053。</p><p>\u53d7\u5f71\u54cd\u7684\u662f\u5f00\u53d1\u7a97\u53e3 development-00-f800 \u7684\u5de6\u5e76\u7ebf\u5019\u9009 31，\u4ee5\u53ca\u7b2c\u4e8c\u6761\u771f\u5b9e\u5de6\u5e76\u7ebf\u5728 GPS146\u79d2\u7684\u5019\u900928、150\u79d2\u7684\u5019\u900941。\u56e0\u6b64\u4e0a\u6587“\u627e\u5230\u5de6\u5e76\u7ebf\u5019\u9009”\u7684\u7ed3\u679c\u4f9d\u8d56\u539f\u6709\u671d\u5411\u5047\u8bbe，\u4e0d\u80fd\u5f53\u4f5c\u7a33\u5065\u7684\u5e76\u7ebf\u5b8c\u6210\u65b9\u6848。5 \u6761\u5b9e\u9645\u6807\u6ce8\u5efa\u8bae\u4e2d\u6709 2 \u6761\u53d7\u5f71\u54cd；\u5176\u4f59 3 \u6761\u6ca1\u6709\u51fa\u73b0\u8fd9\u9879\u51e0\u4f55\u7ed3\u679c\u53d8\u5316，\u4f46\u4ecd\u672a\u9a8c\u8bc1\u8f66\u8f86\u63a7\u5236。</p><img src="heading-sensitivity.png" alt="\u540c\u4e00\u8f66\u8eab\u4e2d\u5fc3\u4f4d\u7f6e\u4e0b，\u4e24\u79cd\u8f66\u5934\u65b9\u5411\u5bfc\u81f4\u8f66\u89d2\u8d8a\u8fc7\u76ee\u6807\u8f66\u9053\u8fb9\u754c"><p>\u56fe\u4e2d\u7eff\u8272\u4e3a\u76ee\u6807\u9053\u8def\u533a\u57df。\u7eff\u8272\u8f66\u6846\u6309\u539f\u89c4\u5219\u5b8c\u5168\u4f4d\u4e8e\u5176\u4e2d，\u7ea2\u8272\u8f66\u6846\u4f7f\u7528\u66ff\u4ee3\u671d\u5411\u540e\u6709\u4e00\u90e8\u5206\u8d8a\u754c。\u6240\u6709\u539f\u59cb\u7ed3\u679c\u4fdd\u7559\u7528\u4e8e\u6bd4\u8f83；\u5019\u9009\u6f14\u793a\u5df2\u663e\u793a\u5bf9\u5e94\u8bca\u65ad\u63d0\u793a。\u540e\u7eed\u5e94\u68c0\u67e5\u66f4\u591a\u5019\u9009\u5e76\u5728\u751f\u6210\u5efa\u8bae\u65f6\u8003\u8651\u671d\u5411\u548c\u8f66\u8eab\u4f59\u91cf，\u800c\u4e0d\u662f\u653e\u5bbd\u76ee\u6807\u8f66\u9053\u5224\u5b9a。</p>'
        distances='、'.join(f'{r["maximum_vertex_outside_m"]*1000:.1f}' for r in heading['illustrated_failures'])
        extra_sections+=f'<p>\u56fe\u4e2d\u4e09\u4e2a\u6848\u4f8b\u7684\u6700\u8fdc\u8f66\u89d2\u5206\u522b\u8d85\u51fa\u76ee\u6807\u533a\u57df\u7ea6 {distances} \u6beb\u7c73，\u4ec5\u53d1\u751f\u5728\u9884\u6d4b\u7b2c5.5\u79d2\u7684\u68c0\u67e5\u70b9。\u8fd9\u662f\u5c0f\u4f59\u91cf\u654f\u611f\u6027，\u4e0d\u662f\u6574\u8f66\u9a76\u51fa\u9053\u8def\u6216\u5df2\u8bc1\u5b9e\u5b9e\u8f66\u5371\u9669；\u4e5f\u4e0d\u80fd\u901a\u8fc7\u653e\u5bbd\u5224\u5b9a\u628a\u5b83\u9690\u85cf。</p>'
