        extra_sections+='<h2>\u7b2c\u4e8c\u6bb5\u89c6\u9891\u4e3a\u4ec0\u4e48\u5c11\u4e00\u5e27</h2><p>\u7b2c\u4e8c\u6bb5\u8bb0\u5f55\u7684 GPS \u6709 1,235 \u884c，\u524d\u65b9\u76f8\u673a\u89c6\u9891\u53ea\u6709 1,234 \u5e27。\u6309\u5df2\u68c0\u67e5\u7684\u5bfc\u51fa\u5668\u53ca\u5df2\u5b89\u88c5 SDK \u7684\u76f8\u673a\u67e5\u8be2\u89c4\u5219，\u6070\u597d\u6700\u540e\u4e00\u884c GPS \u6ca1\u6709\u524d\u65b9\u76f8\u673a\u8bb0\u5f55，\u5176\u4f59\u884c\u5404\u6709\u4e00\u4e2a\u76f8\u673a\u5339\u914d。\u8fd9\u652f\u6301“\u6700\u540e\u4e00\u5f20\u56fe\u7247\u88ab\u7701\u7565”\u7684\u89e3\u91ca。</p><table><tr><th>\u8bb0\u5f55</th><th>GPS \u884c</th><th>\u524d\u65b9\u89c6\u9891\u5e27</th><th>\u65e0\u76f8\u673a\u5339\u914d\u7684 GPS \u884c（\u4ece 0 \u5f00\u59cb）</th></tr>'+''.join(table)+'</table><p>\u8fd9\u662f\u6e90\u4ee3\u7801\u884c\u4e3a\u548c\u6570\u636e\u5e93\u8bb0\u5f55\u652f\u6301\u7684\u6761\u4ef6\u6027\u5bf9\u5e94\u5173\u7cfb；\u53d1\u5e03\u89c6\u9891\u7684\u751f\u6210\u7248\u672c\u53ca\u539f\u59cb\u56fe\u7247\u9010\u5f20\u5339\u914d\u4ecd\u672a\u72ec\u7acb\u8ba4\u8bc1。\u65e9\u671f alignment-audit.json \u4fdd\u7559\u521d\u6b21\u53d1\u73b0\u5dee\u5f02\u65f6\u7684\u4e0d\u786e\u5b9a\u5224\u65ad，camera-lookup-audit.json \u662f\u540e\u7eed\u8bc1\u636e。</p>'
